CREATE TABLE users (id text PRIMARY KEY, name text NOT NULL, admin boolean NOT NULL DEFAULT false);
CREATE TABLE grants (user_id text NOT NULL REFERENCES users, app_id text NOT NULL, environment text NOT NULL CHECK(environment IN ('dev','prod')), permission text NOT NULL CHECK(permission IN ('use','develop')), PRIMARY KEY(user_id,app_id,environment,permission));
CREATE TABLE apps (id text PRIMARY KEY, name text NOT NULL);
CREATE TABLE releases (id uuid PRIMARY KEY, app_id text NOT NULL REFERENCES apps, version text NOT NULL, artifact_hash text NOT NULL, manifest jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(app_id,version));
CREATE TABLE installations (id uuid PRIMARY KEY, app_id text NOT NULL REFERENCES apps, environment text NOT NULL CHECK(environment IN ('dev','prod')), release_id uuid NOT NULL REFERENCES releases, db_status text NOT NULL DEFAULT 'not_prepared', runtime_status text NOT NULL DEFAULT 'not_deployed', desired_state text NOT NULL DEFAULT 'stopped', UNIQUE(app_id,environment));
CREATE TABLE jobs (id uuid PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations, release_id uuid NOT NULL REFERENCES releases, actor text NOT NULL REFERENCES users, idempotency_key text NOT NULL, input_hash text NOT NULL, status text NOT NULL DEFAULT 'queued', step text NOT NULL DEFAULT 'queued', error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor,idempotency_key));
CREATE TABLE db_resources (installation_id uuid PRIMARY KEY REFERENCES installations, database_name text NOT NULL UNIQUE, owner_role text NOT NULL UNIQUE, migration_role text NOT NULL UNIQUE, runtime_role text NOT NULL UNIQUE, migration_secret text NOT NULL, runtime_secret text NOT NULL);
CREATE TABLE sessions (id_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users, access_token text NOT NULL, refresh_token text NOT NULL, csrf text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE login_flows (state_hash text PRIMARY KEY, verifier text NOT NULL, nonce text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE audit (id bigserial PRIMARY KEY, actor text, action text NOT NULL, target text, request_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
